import itertools


def subsets(universe):
    items = list(universe)
    for mask in range(1 << len(items)):
        yield frozenset(items[i] for i in range(len(items)) if (mask >> i) & 1)


def exists_not(U, X, Y):
    # "Some X are not Y"
    return any(i in X and i not in Y for i in U)


def not_all_in(U, X, Y):
    # "Not all X are Y"
    return not all(i in Y for i in X)


# Each option: (premise, conclusion) as functions of (universe, X, Y).
forms = {
    "original": (
        lambda U, G, C: exists_not(U, G, C),      # some good things are not cheap
        lambda U, G, C: not_all_in(U, C, G),      # not all cheap things are good
    ),
    "A": (
        lambda U, H, P: not_all_in(U, H, P),      # not all Hunan people like pepper
        lambda U, H, P: exists_not(U, P, H),      # some pepper-lovers are not from Hunan
    ),
    "B": (
        lambda U, P, S: exists_not(U, P, S),      # some people are not selfish
        lambda U, P, S: not_all_in(U, P, S),      # people are not all selfish
    ),
    "C": (
        lambda U, M, E: exists_not(U, M, E),      # good motive not necessarily good effect
        lambda U, M, E: exists_not(U, E, M),      # good results not necessarily from good motives
    ),
    "D": (
        lambda U, S, C: exists_not(U, S, C),      # some southerners are not Cantonese
        lambda U, S, C: not_all_in(U, C, S),      # not all Cantonese are southerners
    ),
}

MAX_N = 3


def search(prem, concl):
    checked = 0
    for n in range(1, MAX_N + 1):
        U = range(n)
        for X in subsets(U):
            for Y in subsets(U):
                checked += 1
                if prem(U, X, Y) and not concl(U, X, Y):
                    return {"n": n, "X": sorted(X), "Y": sorted(Y), "checked": checked}
    return {"n": None, "checked": checked}


results = {}
for name, (prem, concl) in forms.items():
    results[name] = search(prem, concl)

print(f"Exhaustive search over universes of size 1..{MAX_N} (bounded, not a universal proof)")
for name in ["original", "A", "B", "C", "D"]:
    r = results[name]
    if r["n"] is None:
        print(f"Form {name}: no counterexample in {r['checked']} models (sampled search only)")
    else:
        print(f"Form {name}: COUNTEREXAMPLE universe size={r['n']}, "
              f"X={r['X']}, Y={r['Y']} -> premise TRUE, conclusion FALSE")

# B's conclusion is the quantifier-dual of its premise, so equivalence holds for all sizes.
b_equiv = all(
    forms["B"][0](range(n), X, Y) == forms["B"][1](range(n), X, Y)
    for n in range(1, MAX_N + 1)
    for X in subsets(range(n))
    for Y in subsets(range(n))
)
print(f"Form B premise and conclusion agree on all models size 1..{MAX_N}: {b_equiv}")
print("B is valid in general by quantifier duality (not X-all => some X not) ")

invalid = sorted(k for k in ["A", "B", "C", "D"] if results[k]["n"] is not None)
print(f"Invalid options found by search: {invalid}")

claimed = "C"
print(f"Claimed answer: {claimed}")
if results[claimed]["n"] is not None:
    print("CHECK PASS: option C is invalid (counterexample found above)")
else:
    print("CHECK FAIL: no counterexample found for option C")

if invalid == [claimed]:
    print("CHECK PASS: C is the unique invalid option")
else:
    print(f"CHECK FAIL: C is not the unique invalid option; also invalid: "
          f"{[k for k in invalid if k != claimed]}")
